CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'ANALYST', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE log_events (id BIGSERIAL PRIMARY KEY, event_timestamp TIMESTAMPTZ NOT NULL, source_type VARCHAR(30) NOT NULL, username VARCHAR(190), ip VARCHAR(64), host VARCHAR(190), action VARCHAR(100) NOT NULL, outcome VARCHAR(30), raw JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX idx_logs_timestamp ON log_events(event_timestamp); CREATE INDEX idx_logs_ip ON log_events(ip); CREATE INDEX idx_logs_username ON log_events(username);
CREATE TABLE detection_rules (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, params JSONB NOT NULL DEFAULT '{}'::jsonb, enabled BOOLEAN NOT NULL DEFAULT true, mitre_technique_id VARCHAR(20));
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, event_id BIGINT REFERENCES log_events(id), source VARCHAR(20) NOT NULL, risk_score INTEGER NOT NULL, severity VARCHAR(20) NOT NULL, reasons TEXT NOT NULL, mitre_technique_id VARCHAR(20), status VARCHAR(30) NOT NULL DEFAULT 'NEW', assignee_id BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_alert_status_severity ON alerts(status,severity);
CREATE TABLE incident_notes (id BIGSERIAL PRIMARY KEY, alert_id BIGINT NOT NULL REFERENCES alerts(id), author_id BIGINT REFERENCES users(id), note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE mitre_techniques (id VARCHAR(20) PRIMARY KEY, name VARCHAR(190) NOT NULL, tactic VARCHAR(120));
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action VARCHAR(100) NOT NULL, target_type VARCHAR(80), target_id VARCHAR(80), details JSONB NOT NULL DEFAULT '{}'::jsonb, ip VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO mitre_techniques(id,name,tactic) VALUES ('T1110','Brute Force','Credential Access'),('T1078','Valid Accounts','Defense Evasion'),('T1005','Data from Local System','Collection'),('T1046','Network Service Discovery','Discovery'),('T1048','Exfiltration Over Alternative Protocol','Exfiltration') ON CONFLICT DO NOTHING;
INSERT INTO detection_rules(name,params,enabled,mitre_technique_id) VALUES ('Brute force','{"threshold":5,"windowMinutes":5}',true,'T1110'),('Off-hours access','{"startHour":8,"endHour":19}',true,'T1078'),('Bulk file access','{"threshold":20}',true,'T1005') ON CONFLICT DO NOTHING;
